var vacationIds = functions.getValues().VacationIds;
ESS.network.sendRequest(`/api/functions/GetVacationKindsInfo?vacationIds=${vacationIds}`)
.then(function (vacationKindsInfo) {
  var vacationKindArray = [];
  vacationKindsInfo.forEach(function (vacationKindInfo) {
    vacationKindArray.push(vacationKindInfo.id);
  });
  var rows = functions.getValues().NewVacationDateGrid;
  rows.forEach(row => {
    if (row.rowValues.VacationKindId && !vacationKindArray.includes(Number(row.rowValues.VacationKindId))) {
      functions.removeItem('NewVacationDateGrid', row.rowIndex);
    }
  });
  if (vacationKindArray.length == 1) {
    functions.setDataSource('VacationKindId', `/api/functions/GetVacationKindsInfo?vacationIds=${vacationIds}`, vacationKindArray[0]);
  } else {
    functions.setDataSource({
      parameterName: 'VacationKindId', 
      newDataSource: `/api/functions/GetVacationKindsInfo?vacationIds=${vacationIds}`,
      shouldSaveValue: true
    });
  }
  // Меняем значение только если это перенос из задания на подтверждение.
  if (functions.getValues().AssignmentId != 0) {
    const vacationIdsCount = JSON.parse(functions.getValues().VacationIds ??= "[]").filter(x => x).length;
    functions.setValue('VacationIdsCount', vacationIdsCount);
  }
});

facilityFormItem.itemAddedEventHandler:
var vacationIds = functions.getValues().VacationIds;
ESS.network.sendRequest(`/api/functions/GetVacationKindsInfo?vacationIds=${vacationIds}`)
.then(function (vacationKindsInfo) {
  if (vacationKindsInfo.length == 1) {
    var rows = functions.getValues().NewVacationDateGrid;
    functions.setValue('NewVacationDateGrid', vacationKindsInfo[0].id, rows[rows.length-1].rowIndex, 'VacationKindId')
  } 
})

facilityFormItem.itemRemovedEventHandler:
var rows = functions.getValues().NewVacationDateGrid;
var vacationKindIdsArray = [];
var beginDateArray = [];
var vacationDurationArray = [];
var endDateArray = [];
var VacationsData = '';
rows.forEach(row => {
  if (row.rowValues.VacationKindId && row.rowValues.BeginDate && row.rowValues.VacationDuration) {
    vacationKindIdsArray.push(row.rowValues.VacationKindId);
    var beginDate = `"${row.rowValues.BeginDate}"`;
    beginDateArray.push(beginDate);
    vacationDurationArray.push(row.rowValues.VacationDuration);
    var endDate = `"${row.rowValues.EndDate}"`;
    endDateArray.push(endDate);
    VacationsData += row.rowValues.VacationKindId + '~' + row.rowValues.BeginDate + '~' + row.rowValues.EndDate +'!';
  };
});
functions.setValue('VacationsData', VacationsData);
var vacationIds = functions.getValues().VacationIds;
var urlTemplate = `/api/functions/CheckAllVacationShiftDates?vacationIds=${vacationIds}&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
ESS.network.sendRequest(urlTemplate).then(function (errors){
  if(errors.length > 0) {
    functions.removeError(context.errorVacations);
    context.errorVacations = functions.showError(errors);
  } else {
    functions.removeError(context.errorVacations);
  }
});
var urlTemplate = `/api/functions/CheckShiftingVacationsDurations?vacationIds=${vacationIds}&vacationKindIds=[${vacationKindIdsArray}]&durations=[${vacationDurationArray}]`;
ESS.network.sendRequest(urlTemplate).then(function (durationErrors){
  if(durationErrors.length > 0) {
    functions.removeError(context.errorDurations);
    context.errorDurations = functions.showError(durationErrors);
  } else {
    functions.removeError(context.errorDurations);
  }
});
var urlTemplate = `/api/functions/CheckExecutionShiftVacations?vacationIds=${vacationIds}`;
ESS.network.sendRequest(urlTemplate).then(function (errors){
  if(errors.length > 0) {
    functions.removeError(context.errorExecutionShift);
    context.errorExecutionShift = functions.showError(errors);
  } else {
    functions.removeError(context.errorExecutionShift);
  }
});

