facilityFormItem.onClickEventHandler:
        const id = 'shiftVacationSimplePlanningTool';
        let intervalId;
        const callDialog = () => {
          if (!Object.keys(context.canShowDialog).length) {
            const timeline = {
              type: ESS.enums.DialogItemType.TEXT,
              name: 'timeline',
              properties: {
                text: `
                  <component
                    name="VacationPlanningTool"
                    public-name="Directum_VacationPlanningTool_1_0"
                    module-name="loaders"
                    loader-name="lk-loader"
                    dialog-id="${id}"
                  />
                `,
              },
            };

            const newVacations = {
              type: ESS.enums.DialogItemType.INPUT,
                name: 'Vacations',
                properties: {
                  initialValue: JSON.stringify(functions.getValues().NewVacationDateGrid),
                  isHidden: true,
                },
            }

            const oldVacations = {
              type: ESS.enums.DialogItemType.INPUT,
                name: 'OldVacations',
                properties: {
                  initialValue: functions.getValues().VacationIds,
                  isHidden: true,
                },
            }

            const performerId = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'PerformerId',
              properties: {
                initialValue: functions.getValues().InitiatorId,
                isHidden: true,
              },
            };

            const entityGuid = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'EntityGuid',
              properties: {
                initialValue: '6e7a8c95-aa2b-44f3-ae0c-6f748a0e68ac',
                isHidden: true,
              },
            };

            const assignmentId = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'AssignmentId',
              properties: {
                initialValue: functions.getValues().AssignmentId,
                isHidden: true,
              },
            };

            const items = [
              timeline,
              performerId,
              newVacations,
              oldVacations,
              entityGuid,
              assignmentId,
            ];

            ESS.dialogs.createDialog({
              id,
              properties: {
                width: ESS.enums.DialogWidth.WIDE,
                isFullScreen: true,
              },
              title: ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_DIALOG_TITLE'),
              items,
            });
            clearInterval(intervalId);
          }
        }

        intervalId = setInterval(callDialog, 300);

facility.openingEventHandler:
    context.canShowDialog = {};
    context.sendRequest = (...args) => {
      const key = Date.now();
      context.canShowDialog[key] = '';
      return ESS.network.sendRequest(...args).finally(() => delete context.canShowDialog[key]);
    };
    context.checkEmployeeConsentSigned = ESS.scripts.HRProVacations.checkEmployeeConsentSigned;
    context.setDataSource = (initiatorId, vacationId, formItems) => {
      formItems.forEach(item => {
        var confirmationAssignmentId = functions.getValues().AssignmentId;
        confirmationAssignmentId = confirmationAssignmentId == 0 ? null : confirmationAssignmentId;
        ESS.network.sendRequest(`/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${initiatorId}&confirmationAssignmentId=${confirmationAssignmentId}&vacationId=${vacationId}&isForReworkCardOpen=false`)
          .then((response) => functions.setValue('VacationsCount', response.length));
        functions.setDataSource(item, `/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${initiatorId}&confirmationAssignmentId=${confirmationAssignmentId}&vacationId=${vacationId}&isForReworkCardOpen=false`);
      });
    };

    context.getVacationStatementTemplateId = (initiatorId) => {
      ESS.network.sendRequest(`/api/functions/GetVacationStatementTemplateId?employeeId=${initiatorId}&isShiftVacation=true`)
        .then(function (VacationStatementData) {
          if (VacationStatementData.Error.length == 0) {
            var templateId = ESS.parseFloat(VacationStatementData.TemplateId);
            var docKindId = ESS.parseFloat(VacationStatementData.DocumentKindId);
            functions.setValue('TemplateId', templateId);
            functions.setValue('DocumentKindId', docKindId);
            functions.setValue('IsFromEssAccount', true);
          } else {
            ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), VacationStatementData.Error);
          }
        })
        .catch(function (error) {
          ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
        });
    };

    if (!functions.getValues().AssignmentId){
      functions.setValue('AssignmentId', 0);
      functions.setValue('Field_Дата подписи', new Date().toLocaleDateString('ru-RU'));
      const initiatorId = functions.getValues().Initiator;
      context.checkEmployeeConsentSigned({ functions, context, employeeId: initiatorId });
      ESS.network.sendRequest(`/api/functions/GetEmployeeCertificates`)
      .then(function (certs) {
        if (certs.length == 0) {
          ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_SENDSTATEMENT_NO_CERTIFICATES_ERROR'));
          reject();
        } else {
          ESS.network.sendRequest(`/api/functions/GetPostListByPerson`)
          .then(function (employee){
              ESS.network.sendRequest(`/api/functions/CheckEmployeeConsentSigned`)
              .then(function (isConsentSigned) {
                if (isConsentSigned != true && employee.positions.length == 1) 
                {
                  ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_SHIFTVACATION_CONSENT_ERROR'));       
                  reject();  
                } else {
                  const primaryId = employee.positions.find(emp => emp.isPrimary).id;
                  functions.setDataSource('VacationId', `/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${primaryId}&confirmationAssignmentId=${null}&vacationId=${null}&isForReworkCardOpen=false`);
                  functions.setDataSource('VacationId2', `/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${primaryId}&confirmationAssignmentId=${null}&vacationId=${null}&isForReworkCardOpen=false`);
                  functions.setDataSource('VacationId3', `/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${primaryId}&confirmationAssignmentId=${null}&vacationId=${null}&isForReworkCardOpen=false`); 
                  ESS.network.sendRequest(`/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${primaryId}&confirmationAssignmentId=${null}&vacationId=${null}&isForReworkCardOpen=false`)
                    .then((response) => {
                      functions.setValue('VacationsCount', response.length);
                      // Если это не перенос из задания на подтверждение, то устанавливаем значение равное количеству доступных к переносу отпусков.
                      functions.setValue('VacationIdsCount', response.length);
                    });
                  functions.setValue('InitiatorId', primaryId);
                  functions.addItem('NewVacationDateGrid');
                  context.getVacationStatementTemplateId(initiatorId);
                  resolve();
                }
              });                        
          })                
        }
      })
      .catch(function (error) {
        ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
      });
    }
    else {
      var initiatorId = functions.getValues().InitiatorId;
      var confirmationAssignmentId = functions.getValues().AssignmentId;
      ESS.network.sendRequest(`/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${initiatorId}&confirmationAssignmentId=${confirmationAssignmentId}&vacationId=${null}&isForReworkCardOpen=false`)
        .then(function (response){
          functions.setValue('VacationsCount', response.length);
          if (response.length == 1)
          {
            functions.setDataSource('VacationId', `/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${initiatorId}&confirmationAssignmentId=${confirmationAssignmentId}&vacationId=${null}&isForReworkCardOpen=false`, response[0].id);
            functions.setIsItemDisabled('VacationId', true); 
          }
          else 
            context.setDataSource(initiatorId, null, ["VacationId", "VacationId2", "VacationId3"]);
          functions.addItem('NewVacationDateGrid');
          resolve();  
          })
        .catch(function (error) {
        ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
      });   
      context.getVacationStatementTemplateId(initiatorId);
    }

facility.closingEventHandler:
var totalVacations = functions.getValues().VacationsCount;
var selectedVacations = functions.getValues().VacationIdsCount;
context.needCloseConfirmation = totalVacations == selectedVacations;
resolve();

facility.closedEventHandler:
if (sender.performingAction === 'SUBMIT_FACILITY_PARAMETERS') {
  if (context.needCloseConfirmation) {
    ESS.closeElement(sender.parent);
  } else {
    ESS.updateElement(sender.parent);
  }
  ESS.widgets.updateWidgets();
}
